def _descripcion(objeto):
    for campo in ('descripcion', 'instrucciones', 'observaciones'):
        valor = getattr(objeto, campo, '') or ''
        if valor:
            return valor
    return ''


def cargar_taxonomia_y_codigos(apps, schema_editor):
    Unidad = apps.get_model('webcitt', 'Unidad')
    Familia = apps.get_model('webcitt', 'FamiliaProducto')
    Producto = apps.get_model('webcitt', 'Producto')
    Receta = apps.get_model('webcitt', 'Receta')
    Etapa = apps.get_model('webcitt', 'EtapaReceta')
    PlanCalidad = apps.get_model('webcitt', 'PlanCalidad')
    ParametroCalidad = apps.get_model('webcitt', 'ParametroCalidad')
    Guia = apps.get_model('webcitt', 'GuiaActividadReserva')
    Simulacion = apps.get_model('webcitt', 'SimulacionGuardada')
    UnidadEquipo = apps.get_model('webcitt', 'UnidadEquipo')
    AliasEquipo = apps.get_model('webcitt', 'AliasCodigoUnidadEquipo')
    Reserva = apps.get_model('webcitt', 'Reserva')
    Ficha = apps.get_model('webcitt', 'FichaContenido')
    ContentType = apps.get_model('contenttypes', 'ContentType')

    familias = {}
    prefijos = {}
    for slug, (prefijo, nombres) in TAXONOMIA.items():
        unidad = Unidad.objects.filter(slug=slug, dependencia='plantas_piloto').first()
        if unidad is None:
            continue
        prefijos[unidad.pk] = prefijo
        for orden, nombre in enumerate(nombres, start=1):
            familia, _ = Familia.objects.update_or_create(
                unidad_id=unidad.pk,
                orden=orden,
                defaults={'codigo': f'{prefijo}-F{orden:02d}', 'nombre': nombre, 'descripcion': '', 'activa': True},
            )
            familias[(unidad.pk, orden)] = familia

    for producto in Producto.objects.filter(unidad__dependencia='plantas_piloto').select_related('unidad'):
        orden = PRODUCTOS_ESPECIALES.get(producto.codigo)
        if orden is None:
            orden = LINEAS_A_ORDEN.get(producto.unidad.slug, {}).get(producto.linea)
        if orden is not None:
            producto.familia_id = familias[(producto.unidad_id, orden)].pk
            producto.save(update_fields=['familia'])

    for receta in Receta.objects.filter(unidad__dependencia='plantas_piloto').select_related('producto'):
        receta.familia_id = receta.producto.familia_id
        receta.save(update_fields=['familia'])
        Etapa.objects.filter(receta_id=receta.pk).update(familia_id=receta.familia_id)

    for plan in PlanCalidad.objects.filter(unidad__dependencia='plantas_piloto').select_related('producto'):
        familia_id = plan.producto.familia_id if plan.producto_id else None
        if familia_id is None:
            parametro = (
                ParametroCalidad.objects.filter(plan_id=plan.pk, etapa__familia__isnull=False)
                .select_related('etapa').first()
            )
            familia_id = parametro.etapa.familia_id if parametro else None
        if familia_id:
            plan.familia_id = familia_id
            plan.save(update_fields=['familia'])

    for simulacion in Simulacion.objects.filter(unidad__dependencia='plantas_piloto').select_related('receta'):
        if simulacion.receta_id and simulacion.receta.familia_id:
            simulacion.familia_id = simulacion.receta.familia_id
            simulacion.save(update_fields=['familia'])

    cambios_codigo = {}
    for equipo in UnidadEquipo.objects.filter(laboratorio__dependencia='plantas_piloto', codigo_unidad__contains='-UNIT-'):
        anterior = equipo.codigo_unidad
        actual = anterior.replace('-UNIT-', '-EQP-', 1)
        AliasEquipo.objects.update_or_create(codigo=anterior, defaults={'unidad_equipo_id': equipo.pk})
        equipo.codigo_unidad = actual
        equipo.save(update_fields=['codigo_unidad'])
        cambios_codigo[anterior] = actual

    if cambios_codigo:
        for reserva in Reserva.objects.filter(laboratorio__dependencia='plantas_piloto'):
            codigo = reserva.equipo_codigo or ''
            seleccion = reserva.unidades_seleccionadas or ''
            codigo_nuevo, seleccion_nueva = codigo, seleccion
            for anterior, actual in cambios_codigo.items():
                codigo_nuevo = codigo_nuevo.replace(anterior, actual)
                seleccion_nueva = seleccion_nueva.replace(anterior, actual)
            campos = []
            if codigo_nuevo != codigo:
                reserva.equipo_codigo = codigo_nuevo
                campos.append('equipo_codigo')
            if seleccion_nueva != seleccion:
                reserva.unidades_seleccionadas = seleccion_nueva
                campos.append('unidades_seleccionadas')
            if campos:
                reserva.save(update_fields=campos)

    modelos = {
        'equipo': UnidadEquipo,
        'producto': Producto,
        'proceso': Receta,
        'pcc': Etapa,
        'especificacion': PlanCalidad,
        'guia': Guia,
    }
    tipos_contenido = {}
    for tipo, Modelo in modelos.items():
        tipos_contenido[tipo], _ = ContentType.objects.get_or_create(
            app_label='webcitt', model=Modelo._meta.model_name,
        )

    for equipo in UnidadEquipo.objects.filter(laboratorio__dependencia='plantas_piloto').select_related('equipo', 'laboratorio'):
        Ficha.objects.update_or_create(
            codigo=equipo.codigo_unidad,
            defaults={
                'unidad_id': equipo.laboratorio_id, 'tipo': 'equipo', 'titulo': equipo.equipo.nombre,
                'descripcion': _descripcion(equipo.equipo), 'estado': 'publicada' if equipo.activa else 'archivada',
                'version': 1, 'visibilidad': 'publica' if equipo.activa else 'interna',
                'content_type_id': tipos_contenido['equipo'].pk, 'object_id': equipo.pk,
            },
        )
    for tipo, Modelo in (('producto', Producto), ('proceso', Receta), ('especificacion', PlanCalidad)):
        for objeto in Modelo.objects.filter(unidad__dependencia='plantas_piloto').select_related('unidad', 'familia'):
            visible = getattr(objeto, 'publico', True) and getattr(objeto, 'activo', getattr(objeto, 'activa', True))
            Ficha.objects.update_or_create(
                codigo=objeto.codigo,
                defaults={
                    'unidad_id': objeto.unidad_id, 'familia_id': objeto.familia_id, 'tipo': tipo,
                    'titulo': objeto.nombre, 'descripcion': _descripcion(objeto),
                    'estado': 'publicada' if visible else 'archivada', 'version': 1,
                    'visibilidad': 'publica' if visible else 'interna',
                    'content_type_id': tipos_contenido[tipo].pk, 'object_id': objeto.pk,
                },
            )
    for etapa in Etapa.objects.filter(
        receta__unidad__dependencia='plantas_piloto', punto_critico=True,
    ).select_related('receta', 'receta__unidad'):
        prefijo = prefijos[etapa.receta.unidad_id]
        codigo_objeto = etapa.receta.codigo.split('-REC-', 1)[-1]
        Ficha.objects.update_or_create(
            codigo=f'{prefijo}-PCC-{codigo_objeto}-{etapa.orden:02d}',
            defaults={
                'unidad_id': etapa.receta.unidad_id, 'familia_id': etapa.familia_id, 'tipo': 'pcc',
                'titulo': etapa.nombre, 'descripcion': etapa.instrucciones,
                'estado': 'publicada' if etapa.receta.activa else 'archivada', 'version': 1,
                'visibilidad': 'publica' if etapa.receta.activa else 'interna',
                'content_type_id': tipos_contenido['pcc'].pk, 'object_id': etapa.pk,
            },
        )
    for guia in Guia.objects.filter(actividad__unidad__dependencia='plantas_piloto').select_related('actividad'):
        Ficha.objects.update_or_create(
            codigo=guia.codigo_guia or f'{prefijos[guia.actividad.unidad_id]}-GUI-{guia.pk:04d}',
            defaults={
                'unidad_id': guia.actividad.unidad_id, 'familia_id': guia.familia_id, 'tipo': 'guia',
                'titulo': guia.titulo, 'descripcion': guia.descripcion,
                'estado': 'publicada' if guia.estado_publicacion == 'publicada' else 'borrador',
                'version': guia.numero_version, 'visibilidad': 'publica' if guia.visibilidad == 'publica' else 'interna',
                'content_type_id': tipos_contenido['guia'].pk, 'object_id': guia.pk,
            },
        )
    for unidad_id, prefijo in prefijos.items():
        for clave, titulo in (
            ('BALANCE', 'Balance de materia y energía'),
            ('LINEA', 'Balance de línea'),
            ('MATERIALES', 'Requerimiento de materiales'),
        ):
            Ficha.objects.update_or_create(
                codigo=f'{prefijo}-SIM-{clave}',
                defaults={
                    'unidad_id': unidad_id, 'tipo': 'simulador', 'titulo': titulo,
                    'descripcion': 'Simulador integrado que usa los datos vigentes de los procesos de la planta.',
                    'estado': 'publicada', 'version': 1, 'visibilidad': 'publica',
                },
            )


def revertir_taxonomia_y_codigos(apps, schema_editor):
    AliasEquipo = apps.get_model('webcitt', 'AliasCodigoUnidadEquipo')
    Reserva = apps.get_model('webcitt', 'Reserva')
    for alias in AliasEquipo.objects.select_related('unidad_equipo'):
        actual = alias.unidad_equipo.codigo_unidad
        anterior = alias.codigo
        for reserva in Reserva.objects.filter(laboratorio__dependencia='plantas_piloto'):
            campos = []
            if actual in (reserva.equipo_codigo or ''):
                reserva.equipo_codigo = reserva.equipo_codigo.replace(actual, anterior)
                campos.append('equipo_codigo')
            if actual in (reserva.unidades_seleccionadas or ''):
                reserva.unidades_seleccionadas = reserva.unidades_seleccionadas.replace(actual, anterior)
                campos.append('unidades_seleccionadas')
            if campos:
                reserva.save(update_fields=campos)
        alias.unidad_equipo.codigo_unidad = anterior
        alias.unidad_equipo.save(update_fields=['codigo_unidad'])
    AliasEquipo.objects.all().delete()


